console.log('Products matching \"wireless\" or \"mouse\":');
results.forEach(p => {
    console.log('\n  Product: ' + p.name + ' (ID: ' + p.product_id + ')');
    const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id=?').all(p.product_id);
    variants.forEach(v => {
        console.log('    Variant ' + v.item_id + ': $' + v.price + ' | Available: ' + (v.available ? 'Yes' : 'No') + ' | Options: ' + v.options);
    });
});
"

