cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Search all products for PROD-FA0948
let results = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%FA0948%' OR name LIKE '%FA0948%'\").all();
console.log('world.db products match:', results);

// Search across all tables for this ID
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
    try {
        const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
        for (const col of cols) {
            const q = 'SELECT * FROM ' + t.name + ' WHERE CAST(\"' + col.name + '\" AS TEXT) LIKE ?';
            try {
                const rows = db.prepare(q).all('%FA0948%');
                if (rows.length > 0) {
                    console.log('Found in', t.name, '.', col.name, ':', rows);
                }
            } catch(e) {}
        }
    } catch(e) {}
}
"
